{
  "Q1": {
    "q1a_rule": {
      "verdict": "yes",
      "rationale": "Identifies FR Doc. 2026-15665, 91 FR 49178–49227, published Aug. 3, 2026, effective Sept. 2, 2026, docket OPM-2025-0107, RIN 3206-AO86."
    },
    "q1b_nprm": {
      "verdict": "yes",
      "rationale": "Identifies the proposed rule as FR Doc. 2026-04377, 91 FR 10904–10934, published March 5, 2026."
    },
    "q1c_first": {
      "verdict": "yes",
      "rationale": "Gives 2026-17335, 91 FR 54794–54796, published Aug. 25, 2026, effective Sept. 2, 2026, and describes the clerical/amendatory-instruction, cross-reference, list-structure, terminology and citation corrections. It does not use the word 'non-substantive', but the described corrections are the typographical/clerical corrections the criterion expects."
    },
    "q1c_second": {
      "verdict": "yes",
      "rationale": "Gives 2026-18800, 91 FR 58363–58364, published and effective Sept. 15, 2026, restoring paragraphs (1)(i) and (1)(ii) of the CTAP definition of 'displaced' in 5 CFR 330.602 and notes they were inadvertently removed."
    },
    "q1d_applicability": {
      "verdict": "yes",
      "rationale": "Correctly makes issuance of the RIF notice the test: notices before Sept. 2 stay under the prior rules; notices on or after Sept. 2 use the amended rules. Locates this in the DATES line, 91 FR 49178, and Implementation Considerations, 91 FR 49206–49207."
    },
    "q1e_appeals": {
      "verdict": "yes",
      "rationale": "Lists 2026-15666, effective Sept. 2, 2026, in force, identifying subpart I and the changes to 351.802(a)(6), 351.807(e), and the appeals process."
    },
    "q1e_leave": {
      "verdict": "yes",
      "rationale": "Lists 2026-21320, says it revises 5 CFR 351.806, effective Nov. 18, 2026, and says it is not yet effective on Nov. 14, 2026."
    },
    "q1e_senior": {
      "verdict": "yes",
      "rationale": "Lists 2026-21316, says it revises 'rating of record' in 351.203 and amends 351.503(a)(1), (b)(2), (b)(3), effective Nov. 18, 2026, and not yet in force."
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "The answer consistently supplies FR document numbers, FR pages, docket/RIN, and CFR provisions."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "No invented FR document, citation, quotation, or CFR paragraph found. The extra 2026-13715 reference is a real document and is not treated as required."
    }
  },
  "Q2": {
    "q2a_abbott": {
      "verdict": "yes",
      "rationale": "Abbott: 7 + 5 + 5 = 17 performance credit, 0 veterans' points, total 17."
    },
    "q2a_bianchi": {
      "verdict": "yes",
      "rationale": "Bianchi: 5 + 0 + 3 = 8, plus 5 for a 30-percent-or-more compensable disability, total 13; Level 2 is correctly scored 0."
    },
    "q2a_castillo": {
      "verdict": "yes",
      "rationale": "Castillo: 7 + 5 + 5 = 17 and 0 veterans' points; correctly explains that a 22-year length-of-service retirement with no qualifying disability is not preference eligible under 351.504(b)."
    },
    "q2a_dalton": {
      "verdict": "yes",
      "rationale": "Dalton: two ratings 7 and 0, proxy (7+0)/2 = 3.5, performance credit 10.5, plus 3 = 13.5."
    },
    "q2a_eze": {
      "verdict": "yes",
      "rationale": "Eze: 5 + 5 + 5 = 15, 0 veterans' points, and correctly placed in tenure subgroup II as a non-career employee past probation."
    },
    "q2a_fontaine": {
      "verdict": "yes",
      "rationale": "Fontaine: one Level 4 rating, 5 × 3 = 15; total 15."
    },
    "q2b_order": {
      "verdict": "yes",
      "rationale": "Order is Abbott, Castillo, Fontaine, Eze, Dalton, Bianchi; both ties are explained: Abbott over Castillo by earlier SCD, Fontaine over Eze because subgroup I outranks subgroup II under 351.501(c)."
    },
    "q2b_released": {
      "verdict": "yes",
      "rationale": "Bianchi and Dalton are the two released employees."
    },
    "q2c_old": {
      "verdict": "yes",
      "rationale": "Says Bianchi would have been above Abbott under the earlier rules because veterans' preference subgroup AD preceded B before service/performance credit, citing the 2026 rule's description at 91 FR 49198 (and 49186)."
    },
    "q2d_records": {
      "verdict": "yes",
      "rationale": "Cites 351.506(b)–(e), says a noticed employee may inspect the complete retention register and related records, including all other employees' names and the information needed to check scoring and relative ranking."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "The calculations and legal propositions are tied to CFR sections and FR pages."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "No invented document, quotation, or CFR paragraph appears."
    }
  },
  "Q3": {
    "q3a_case_a": {
      "verdict": "yes",
      "rationale": "Case A: not preference eligible, 0 points, subgroup B; correctly applies 351.504(b)(1)–(4) (20-year length-of-service retirement, no qualifying disability)."
    },
    "q3a_case_b": {
      "verdict": "yes",
      "rationale": "Case B: not preference eligible, 0 points, subgroup B; correctly treats 351.504(b)(4) as conjunctive for a commander/major-or-above and finds none of (b)(1)–(3) met."
    },
    "q3a_case_c": {
      "verdict": "yes",
      "rationale": "Case C: preference eligible, +5, subgroup AD; armed-conflict disability retirement under (b)(1)(i), with (b)(4) satisfied and 30-percent disability under (a)(1)."
    },
    "q3a_case_d": {
      "verdict": "yes",
      "rationale": "Case D: not preference eligible, 0 points, subgroup B; 24-year length-of-service retirement meets none of (b)(1)–(3)."
    },
    "q3a_case_e": {
      "verdict": "yes",
      "rationale": "Case E: preference eligible under (b)(2) because retired pay is not based on 20+ years; +3 under (a)(2), subgroup A."
    },
    "q3b_scd_a": {
      "verdict": "yes",
      "rationale": "Employee A: only the 2 campaign years count under 351.505(b)(2)(i); Sept. 7, 2010 minus 2 years = Sept. 7, 2008."
    },
    "q3b_scd_c": {
      "verdict": "yes",
      "rationale": "Employee C: as a preference-eligible retiree, all 14 years count under 351.505(b)(2)(ii); Sept. 7, 2010 minus 14 years = Sept. 7, 1996."
    },
    "q3c_labels": {
      "verdict": "yes",
      "rationale": "Explains that AD/A/B are register identifiers and point levels, not separate ranking blocks under the amended rules; ranking uses total credit, then tenure subgroup, then SCD."
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "The table and SCD calculations are supported by CFR paragraphs and FR pages."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "The cited provisions, including 351.504(b)(5), exist; no fabrication found."
    }
  },
  "Q4": {
    "q4a_farah": {
      "verdict": "yes",
      "rationale": "No cutoff: all five ratings are in the four-year period; three most recent are Level 5, Level 3, Level 3, giving 7 + 3 + 3 = 13."
    },
    "q4b_cutoff_date": {
      "verdict": "yes",
      "rationale": "Computes Sept. 3, 2026 minus 45 days = July 20, 2026, with the day count shown."
    },
    "q4b_credit": {
      "verdict": "yes",
      "rationale": "Excludes the Aug. 10, 2026 rating; uses Nov. 2025 Level 3, Nov. 2024 Level 3, and Nov. 2023 Level 4: 3 + 3 + 5 = 11."
    },
    "q4c_not_on_record": {
      "verdict": "yes",
      "rationale": "Correct conditional answer: if Aug. 15 was the first date the rating was available to the register-building office, it cannot be used after the July 20 cutoff; conversely, a late system entry does not disqualify an otherwise available rating."
    },
    "q4d_gina": {
      "verdict": "yes",
      "rationale": "Excludes the Aug. 15, 2022 rating as outside the four-year period; uses 5 and 3, proxy 4, total 12."
    },
    "q4e_modal": {
      "verdict": "yes",
      "rationale": "Says Hank's credit must be based on the modal rating for his summary-level pattern under 351.503(f)(1), and that no numerical credit is established on these facts."
    },
    "q4e_flag": {
      "verdict": "yes",
      "rationale": "Flags that no modal rating is supplied, the modal-rating definition is not printed in the 2026 amendments, and 351.503(f)(1) does not itself spell out the arithmetic."
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "Citations to 351.503 and FR pages are supplied throughout."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "No invented source or quotation detected."
    }
  },
  "Q5": {
    "q5a_i_rules": {
      "verdict": "yes",
      "rationale": "Correctly says the earlier rules apply to the Aug. 28, 2026 notice even though the RIF takes effect Oct. 27, because notice issuance controls."
    },
    "q5a_i_result": {
      "verdict": "yes",
      "rationale": "Uses the final rule's description of the earlier rules—Level 3 = 12 years, Level 5 = 20 years—gives Lee's adjusted date as 1986 and Park's as 1999, and releases Park."
    },
    "q5a_ii": {
      "verdict": "yes",
      "rationale": "Sept. 2 notice uses the amended rules; Lee 9, Park 21; Lee is released."
    },
    "q5a_iii": {
      "verdict": "yes",
      "rationale": "Sept. 3 notice uses the amended rules; Lee is released."
    },
    "q5b_no_recalc": {
      "verdict": "yes",
      "rationale": "Cites 5 CFR 351.805(b) and says an amended notice solely moving the effective date is not a new specific RIF notice and does not require recalculating retention standing."
    },
    "q5c_version": {
      "verdict": "yes",
      "rationale": "Version of the rules is fixed by the date the agency issues the RIF notice under the DATES line and preamble implementation discussion."
    },
    "q5c_window": {
      "verdict": "yes",
      "rationale": "Four-year ratings period ends on issuance of RIF notices, or the agency cutoff date, under 351.503(c)(1)–(2)."
    },
    "q5c_standing": {
      "verdict": "yes",
      "rationale": "Tenure subgroup and retention standing are fixed when the employee receives the specific RIF notice, citing 351.502 and 351.507(a)."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "The answer gives FR pages and CFR provisions for its claims."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "No fabricated source found."
    }
  },
  "Q6": {
    "q6a_reach": {
      "verdict": "yes",
      "rationale": "Correctly treats positions 1, 2 and 3 as reachable and excludes 4 (four grades down), 5 (higher-standing holder), 6 (part-time schedule) and 7 (different competitive area) under 351.701(a)–(b)."
    },
    "q6a_offer": {
      "verdict": "yes",
      "rationale": "Says the required offer is position 1, the GS-12 held by Ellis, because it has the least reduction in representative rate."
    },
    "q6b_five": {
      "verdict": "yes",
      "rationale": "For a 30-percent-or-more disabled preference eligible, the limit becomes five grades, making position 4 (GS-9) reachable; the offer remains position 1."
    },
    "q6c_level1": {
      "verdict": "yes",
      "rationale": "A current annual Level 1 rating does not meet 351.701(a)'s Level 2 minimum, so there is no assignment right."
    },
    "q6d_excepted": {
      "verdict": "yes",
      "rationale": "Says 351.701 does not give mandatory assignment rights in the excepted service; under 351.705(a) the agency may adopt equivalent provisions, so it depends on agency adoption."
    },
    "q6e_level2": {
      "verdict": "yes",
      "rationale": "Says the former Level 2-versus-higher-rating restriction was eliminated, citing 91 FR 49204."
    },
    "q6e_bump": {
      "verdict": "yes",
      "rationale": "Says the separate bumping and retreating concepts were consolidated into the single assignment right to a position held by an employee with lower retention standing."
    },
    "q6_cite": {
      "verdict": "no",
      "rationale": "CFR sections and FR pages are supplied."
    },
    "q6_fab": {
      "verdict": "no",
      "rationale": "The cited 351.701(d) paragraphs exist in the final text; no fabrication."
    }
  },
  "Q7": {
    "q7a_mspb": {
      "verdict": "yes",
      "rationale": "Concludes MSPB hears the appeal because the notice was issued Aug. 31, before the Sept. 2 OPM appeals-rule trigger, not because of the later separation date."
    },
    "q7a_board_rule": {
      "verdict": "yes",
      "rationale": "Cites FR Doc. 2026-16456, 91 FR 51997–51998, and its statement that MSPB will accept cases where the RIF notice was issued before the effective date."
    },
    "q7b_opm": {
      "verdict": "yes",
      "rationale": "For an Oct. 19 notice, says OPM hears the appeal under revised 5 CFR 351.901."
    },
    "q7b_count": {
      "verdict": "yes",
      "rationale": "Shows Dec. 19 as day 1, Jan. 17, 2027 as day 30, and notes Jan. 18 is the MLK federal holiday."
    },
    "q7b_date": {
      "verdict": "yes",
      "rationale": "Gives Tuesday, Jan. 19, 2027 as the last day."
    },
    "q7b_efile": {
      "verdict": "yes",
      "rationale": "Requires filing through OPM's identified electronic filing system and states the 11:59 p.m. Eastern deadline."
    },
    "q7c_burden": {
      "verdict": "yes",
      "rationale": "States the employee's preponderance burden to show noncompliance with a RIF statute or OPM regulation and resulting prejudice under 351.901(b)."
    },
    "q7c_hearing": {
      "verdict": "yes",
      "rationale": "No automatic hearing; review on the written record unless OPM determines a hearing is necessary and efficient under 351.905(c)."
    },
    "q7d_text": {
      "verdict": "yes",
      "rationale": "Says 351.901(c)(2) bars raising the RIF action under a negotiated grievance procedure or grievance arbitration."
    },
    "q7d_flag": {
      "verdict": "yes",
      "rationale": "Reports the preamble's position that existing CBAs are not retroactively invalidated mid-term, that bargaining limits arise on renegotiation, and that existing-agreement questions remain for the chapter 71 forum."
    },
    "q7e_court": {
      "verdict": "yes",
      "rationale": "Says 351.901(c)(4) bars judicial review under subpart I and 351.909(e) denies further appeal of OPM's final decision."
    },
    "q7f_tolling": {
      "verdict": "yes",
      "rationale": "Cites 351.902(b)(3), says a timely OSC complaint can preserve a later RIF appeal if the final decision materially affects retention standing, and gives April 9, 2027."
    },
    "q7g_where": {
      "verdict": "yes",
      "rationale": "Locates the applicability rule in the DATES line, 91 FR 49230, and preamble IV.C.1, 91 FR 49248, and says it is not separately codified in 351.901."
    },
    "q7_cite": {
      "verdict": "no",
      "rationale": "Extensive CFR and FR citations are supplied."
    },
    "q7_fab": {
      "verdict": "no",
      "rationale": "The E8-15622 holiday citation is real and supports the third-Monday January holiday point; no fabrication."
    }
  },
  "Q8": {
    "q8a_adopted": {
      "verdict": "yes",
      "rationale": "Identifies 2026-21320 as revising 351.806, effective Nov. 18, 2026, and not in force on Nov. 14, 2026."
    },
    "q8a_new_text": {
      "verdict": "yes",
      "rationale": "Gives the adopted text: ordinarily duty status, but the agency may place the employee on administrative leave for all or part of the notice period when appropriate and consistent with part 630, subpart N."
    },
    "q8a_today": {
      "verdict": "yes",
      "rationale": "Describes the current rule, as OPM's rulemaking describes it, as keeping the employee in duty status 'when possible'; also describes the emergency lack-of-work-or-funds provision."
    },
    "q8b_consent": {
      "verdict": "yes",
      "rationale": "Says consent is not required, relying on 630.1403(c)(10) and the agency's sole-and-exclusive discretion."
    },
    "q8b_cap": {
      "verdict": "yes",
      "rationale": "Says neither 351.806(b) nor 630.1403(c)(10) establishes a separate numerical maximum and that the leave may cover all or part of the notice period."
    },
    "q8b_12wk": {
      "verdict": "yes",
      "rationale": "Discusses the governmentwide 12-week limit and places its express attachment on 630.1403(c)(9) and (c)(11), not (c)(10)."
    },
    "q8b_flag": {
      "verdict": "yes",
      "rationale": "The answer repeatedly notes the rule is adopted but not yet in force, and it treats the 12-week limit as not expressly attached to (c)(10); this supplies the required caveat for the cap discussion."
    },
    "q8c_guidance": {
      "verdict": "yes",
      "rationale": "Identifies OPM's July 30, 2025 Template for Agency Administrative Leave Policies, CPM 2025-12, as prior guidance already allowing notice-period administrative leave."
    },
    "q8d_no_effect": {
      "verdict": "yes",
      "rationale": "Says the administrative-leave provisions do not alter RIF competition, retention registers or appeal rights."
    },
    "q8_cite": {
      "verdict": "no",
      "rationale": "FR pages and CFR provisions are supplied."
    },
    "q8_fab": {
      "verdict": "no",
      "rationale": "No fabricated source found."
    }
  },
  "Q9": {
    "q9_s1": {
      "verdict": "yes",
      "rationale": "Step 1 noncompliant: 57 days before the Oct. 13 notices is within 90 days, so 351.402(c) required submission of the area description and organizational justification to OPM for advance approval."
    },
    "q9_s3": {
      "verdict": "yes",
      "rationale": "Step 3 noncompliant: supervisory probation is not an initial probationary period; Ortiz is a competing employee and must be ranked."
    },
    "q9_s4": {
      "verdict": "yes",
      "rationale": "Step 4 noncompliant: cutoff is Sept. 13, 2026; the Oct. 2 rating is after the cutoff and using it for only one employee also violates uniform application."
    },
    "q9_s5": {
      "verdict": "yes",
      "rationale": "Step 5 noncompliant: proxy is (7+5)/2 = 6, so credit is 7+5+6 = 18, not 15."
    },
    "q9_s6": {
      "verdict": "yes",
      "rationale": "Step 6 noncompliant: under 351.503(d), extra points for a five-level pattern are not allowed; a written policy does not cure that."
    },
    "q9_s8": {
      "verdict": "yes",
      "rationale": "Step 8 noncompliant: 351.602(a) bars releasing a competing employee while retaining one on a limited temporary or term promotion."
    },
    "q9_s10": {
      "verdict": "yes",
      "rationale": "Step 10 noncompliant: 351.702(a)(4) requires a job-analysis-based skills demonstration and bars sole or principal reliance on an automated self-assessment."
    },
    "q9_s11": {
      "verdict": "yes",
      "rationale": "Step 11 noncompliant: 351.608(a)(3) forbids sequencing or stacking temporary exceptions; the agency may use only one applicable exception."
    },
    "q9_s12": {
      "verdict": "yes",
      "rationale": "Step 12 noncompliant: for notices on or after Sept. 2, 2026, the notice must identify OPM, not MSPB, as the appeal forum, with OPM e-filing information."
    },
    "q9_ok": {
      "verdict": "yes",
      "rationale": "Steps 2, 7 and 9 are all treated as in order, with provisions: 351.202(d)(2)–(3) for step 2, 351.601(c) for step 7, and 351.702(a)(4)(v) for step 9."
    },
    "q9_false2": {
      "verdict": "no",
      "rationale": "The submission does not call step 2 a violation."
    },
    "q9_false7": {
      "verdict": "no",
      "rationale": "The submission does not call step 7 a violation."
    },
    "q9_false9": {
      "verdict": "no",
      "rationale": "The submission does not call step 9 a violation."
    },
    "q9_cite": {
      "verdict": "no",
      "rationale": "Each step is tied to a CFR provision or FR page."
    },
    "q9_fab": {
      "verdict": "no",
      "rationale": "No fabricated source found; cited provisions including 351.608(g) exist."
    }
  },
  "Q10": {
    "q10a_gap": {
      "verdict": "yes",
      "rationale": "Correctly says paragraph (1) had only the introductory text ending in 'who:' because instruction 11 revised paragraph (1) and printed only that introduction, removing (1)(i) and (1)(ii) effective Sept. 2, 2026."
    },
    "q10b_doc": {
      "verdict": "yes",
      "rationale": "Identifies 2026-18800, 91 FR 58363, published and effective Sept. 15, 2026, restoring (1)(i) and (1)(ii)."
    },
    "q10b_reason": {
      "verdict": "yes",
      "rationale": "States OPM's good-cause/no-substantive-change rationale: it restored text in effect before Sept. 2 that OPM had not proposed to remove, and cites 5 U.S.C. 553(b)(B) and (d)(3)."
    },
    "q10c_lower": {
      "verdict": "yes",
      "rationale": "Declining a lower-representative-rate full-time offer does not remove 'displaced' status under (1)(i)."
    },
    "q10c_same": {
      "verdict": "yes",
      "rationale": "Declining a same-representative-rate, same-work-schedule offer does remove 'displaced' status under (1)(i)."
    },
    "q10_cite": {
      "verdict": "no",
      "rationale": "Document numbers, FR pages, and CFR provisions are supplied."
    },
    "q10_fab": {
      "verdict": "no",
      "rationale": "No fabricated source found."
    }
  },
  "Q11": {
    "q11_valid_10": {
      "verdict": "yes",
      "rationale": "Counted in submission order: 1 authority citation (1); 2 351.202(d) scope (1); 3 351.202(d)(1)(ii)/(2)(i)-(ii) issue-vs-receipt timing (3); 4 351.202(d)(2)(iii) temp/term appointments (1); 5 351.202(d)(3)-(4) consequences plus notice (2); 6 furlough definition (1); 7 NOT counted—the 'of this part' error was corrected back to the proposed 'of this chapter', which the key excludes; 8 rating-of-record cross-reference (1); 9 restoration-protected definition (1); 10 351.204 laws/merit principles (1); 11 351.302(d) (1); 12 351.402(c) (1); 13 351.502 issue-vs-receipt (1); 14 351.502(a)(3) temporary appointments (1); 15 351.503 pattern cross-references plus pre-91 FR 41521 reference (2); 16 Level 2 terminology in 351.503(a)(1) and 351.701(a) (2); 17 351.504 should/must (1); 18 351.505(b)(2) cross-reference (1); 19 351.506(c)(1) 'their'/'the employee's' (1); 20 351.506(d) other access rights (1); 21 351.604 not finalized (1); 22 351.605 restructuring plus separate notice paragraph (2); 23 351.606(a) (1); 24 351.608(a)(2) subpart E/F (1); 25 351.702(a)(4)(iii) (1); 26 351.702(a)(4)(v) (1); 27 351.802(a) introductory text (1); 28 351.802(a)(2) veteran status/veterans' preference subgroup (1); 29 351.802(a)(3) access/information on access (1); 30 351.805(b) (1). Total: 36 valid differences."
    },
    "q11_valid_16": {
      "verdict": "yes",
      "rationale": "Same count as q11_valid_10: 36 valid differences."
    },
    "q11_valid_22": {
      "verdict": "yes",
      "rationale": "Same count: 36 valid differences."
    },
    "q11_valid_28": {
      "verdict": "yes",
      "rationale": "Same count: 36 valid differences."
    },
    "q11_valid_34": {
      "verdict": "yes",
      "rationale": "Same count: 36 valid differences, above the 34 threshold."
    },
    "q11_deep": {
      "verdict": "yes",
      "rationale": "States well over six 'deep' differences the summary of changes omitted: 351.502 issue/receipt, Level 2 terminology, should/must, 351.505(b)(2), 351.506(c)/(d), 351.702(a)(4)(iii)/(v), 351.802(a)(2)/(3), 351.302(d), 351.608(a)(2), the 91 FR 41521 reference, and the authority citation."
    },
    "q11_cite": {
      "verdict": "no",
      "rationale": "Each comparison is cited to proposed/final FR pages, with corrections distinguished."
    },
    "q11_fab": {
      "verdict": "no",
      "rationale": "No fabricated document or CFR paragraph found; the correction-only 351.503(b)(2) point is real, though excluded from the proposal-to-final count."
    }
  },
  "Q12": {
    "q12_quinn": {
      "verdict": "yes",
      "rationale": "Quinn is serving an initial probationary period and is not a competing employee; not ranked, but may be retained while competing employees are released."
    },
    "q12_ab": {
      "verdict": "yes",
      "rationale": "Alvarez 7+7+5=19, 0 points; Brandt 3+5+0=8 plus 5 = 13."
    },
